          "id": "eight-predictors",
          "reference": "examples/schemaxis/r-eight-predictors.json"
        },
        {
          "id": "inference",
          "reference": "examples/schemaxis/r-inference.json"
        },
        {
          "id": "inference-variant",
          "reference": "examples/schemaxis/r-inference-variant.json"
        },
        {
