        "tests/unit/test_r_admission.py",
        "tests/unit/test_r_inference.py",
        "tests/unit/test_r_prediction.py",
        "tests/unit/test_r_allocation.py"
      ],
      "acceptance": [
        "tools/qualify_r.py",
        "tools/qualify_r_prediction.py",
        "tools/qualify_r_prediction_gnuplot.py"
      ],
      "profiles": {
        "workflow": {
          "scope": "Verified numeric prediction/fit tables into Calc with preserved numeric columns and independently checked workbook values. Optional prediction.csv with one explicit symmetric halfWidth column feeds one Gnuplot error series through an exact $artifact edge; the x axis is the first declared predictor of the new rows.",
          "references": [
            "docs/r.md",
            "tools/qualify_r.py",
            "examples/schemaxis/r-prediction-to-gnuplot.json",
            "tools/qualify_r_prediction_gnuplot.py"
          ]
        },
        "composition": {
          "scope": "Shared document references, pure values and explicit finite analytic visits; each visit independently validates native fit and requirements.",
          "references": [
            "docs/r.md",
            "tools/qualify_r.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/lm.html",
          "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/predict.lm.html",
          "https://stat.ethz.ch/R-manual/R-devel/library/base/html/readRDS.html",
          "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/summary.lm.html",
          "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/confint.html"
        ],
        "lifecycle": {
          "timeout": "One total deadline covers fit, saved-model reopen and final independent CPU verification; shared native kit has a separate bounded watchdog. Qualified live: with a prediction request the runner times out while the genuine R engine of the reopen/predict.lm stage is running (qualifier-owned clock advanced once the engine PID exists), the stage process group is gone and no success is published; predict.lm position is not instrumented.",
          "cancellation": "Owned process cancellation covers native stages; cancellation is checked again before successful publication. Qualified live: a cancel event raised while the genuine R engine of the reopen/predict.lm stage runs ends RUNNER_CANCELLED with the stage PID and process group gone and no success publication.",
          "logs": "Retain authored/effective plans, canonical numeric inputs, fixed native worker, launcher/input bindings, model.rds, native tables, optional native inference/statistics tables, runtime records, stage stdout/stderr/submissions and failed/success results. With prediction, also prediction-input.csv and native prediction/prediction-statistics tables for both fit and reopen.",
          "verification": "Independent column-scaled Householder QR reconstructs coefficients/predictions/residuals; actual rectangular infinity-norm condition from QR unit-vector solves gates unsupported designs. Compare native model rank/df, fit values and fresh-process RDS replay; recompute finite requirements from checked native values. Launcher/source/model bindings reject stale readback even with refreshed ordinary hashes. Retained regular descriptor reads are nonblocking and bounded8MiB. Optional inference compares native summary.lm/confint/pf values with QR-derived standard errors and standard-library Student-t/F tails, exact level/df readback and fit/reopen equality. Optional prediction intervals call stats::predict.lm for both interval types and compare fit, se.fit, sigma, df, critical value and all four bounds with independent QR leverage h=|R^-T x|^2 and Student-t bisection, relative 1e-5 on widths plus a response-roundoff fit allowance scaled by design magnitude; leverage above 1e4 is refused before native execution."
        },
        "data": [
          {
            "id": "numeric-table",
            "direction": "output",
            "kind": "table",
            "format": "numeric CSV",
            "traits": {
              "columns": "numeric",
              "rows": "at most512"
            },
            "losses": [
              "Coefficient labels and physical unit meaning require accompanying summary.",
              "Finite authored rows only; no physical or generalisation guarantee."
            ],
            "scope": "Coefficient indices/estimates, training observations/predictions/residuals, and optional held-out predictions."
          },
          {
            "id": "summary",
            "direction": "output",
            "kind": "text",
            "format": "JSON",
            "traits": {
              "model": "additive numeric OLS"
            },
            "losses": [
              "No causal inference, multiplicity adjustment or continuous/future prediction proof; optional coefficient inference and optional new-row prediction intervals hold only under the stated error assumptions, and extrapolation is reported, not validated."
            ],
            "scope": "Named coefficients/unit descriptors, numerical conditioning/rank, actual native fit metrics, optional classical inference with assumptions, and explicit acceptance."
          },
          {
            "id": "inference-table",
            "direction": "output",
            "kind": "table",
            "format": "numeric CSV",
            "traits": {
              "columns": "numeric",
              "rows": "at most9"
            },
            "losses": [
              "Coefficient names, units, confidence level and assumptions require the accompanying summary.",
              "Valid only under independent, constant-variance, normal errors and a correct additive mean."
            ],
            "scope": "Optional per-coefficient estimate, standard error, t statistic, two-sided p-value and confidence limits, appended after the summary."
          },
          {
            "id": "prediction-table",
            "direction": "output",
            "kind": "table",
            "format": "numeric CSV",
            "traits": {
              "columns": "numeric",
              "rows": "at most64"
            },
            "losses": [
              "Predictor names, units, interval type, level, degrees of freedom and assumptions require the accompanying summary.",
              "Nominal interval under independent, constant-variance, normal errors and a correct additive mean; not a coverage guarantee, held-out validation or calibration certificate."
            ],
            "scope": "Optional new-row identity, predictors x1..xN, fit, requested interval lower/upper bounds and symmetric half width, appended after any inference table."
          }
        ],
        "inspection": [
          {
            "panel": "table",
            "scope": "Inspect finite numeric native predictions and signed residuals, preserving sample order.",
            "limits": "At most512 rows; no statistical plots or native interactive editor."
          },
