            "panel": "text",
            "scope": "Review declared units, coefficients, measured metrics, optional coefficient inference and assumptions, signed bound margins and numerical fidelity limits.",
            "limits": "RDS remains native evidence, not imported or cross-machine interchange."
          }
        ],
        "authoring": {
          "model": "document",
          "example": "baseline",
          "reuse": "Edit inline rows/model/requirement pointers or source JSON; plan fresh revision, run, inspect residuals and verify. Successful unchanged inputs share durable draft/property/console reuse."
        },
